  str_season_maze_s3_help_title_705 = "幻珠繼承",
  str_season_maze_s3_help_disc_101 = "過往夢境中的不穩定因素仍然在夢域裡蠢蠢欲動，等待時機反噬現實。在啟迪者的幫助下重返夢境，體驗風格各異的探索活動，不斷提升在夢境中的實力，就有機會打倒「終極噬夢者」，使夢境能量恢復平穩。",
  str_season_maze_s3_help_disc_102 = "導航員將帶領啟迪者借助「卜夢卡」的力量，移動至各個「夢域」並觸發該「夢域」的事件；在探索過程中，導航員可以召喚光靈、收集「夢境裝具」、「幻珠」和其他各種夢境資源，以提升自身實力；最終成功挑戰「噬夢暗影」和「終極噬夢者」，便可完成夢境探索，帶回豐富獎勵。",
  str_season_maze_s3_help_disc_201 = "啟迪者會評價導航員在夢境中的表現，記錄「夢境積分」。累積「夢境積分」可以獲得獎勵。",
  str_season_maze_s3_help_disc_202 = "每次探索結束後，啟迪者都會根據「夢境層級」和「探索進度」來記錄「夢境積分」。累積「夢境積分」達到指定階段，即可獲得獎勵。此外，完成「夢境任務」可獲得額外的「夢境積分」。",
  str_season_maze_s3_help_disc_203 = "累積的「夢境積分」達到指定階段，即可獲得獎勵。每隔一段時間會解鎖更多獎勵階段。",
  str_season_maze_s3_help_disc_204 = "夢境中有各式各樣的「夢境任務」。完成「夢境任務」可獲得額外的「夢境積分」。",
  str_season_maze_s3_help_disc_301 = "夢境分為數個層級。夢境層級越高，挑戰越難，挑戰成功後獲得的「夢境積分」也越多。在「夢境層級」頁面會列出該層級活躍的「終極噬夢者」。根據「終極噬夢者」的情報決定探索的策略吧。",
  str_season_maze_s3_help_disc_302 = "初始層級為「夢境層級1」，完成前置層級方可解鎖後續層級。部分層級將隨時間開放。達到「夢境層級3」後，還會解鎖有助探索的「幻珠」系統。",
  str_season_maze_s3_help_disc_303 = "進入夢境時，必須選擇4名光靈加入初始編隊，才能開始探索。編隊中的光靈將繼承夢境外的光靈突破等級，但不會繼承其餘養成屬性和等級。",
  str_season_maze_s3_help_disc_304 = "在「夢境殘響」中將禁用部分光靈，禁用的光靈無法在探索期間召喚。每期「夢境殘響」都會變更禁用的光靈。",
  str_season_maze_s3_help_disc_401 = "在探索過程中，導航員可以操控自己，並攜帶啟迪者進行探索。",
  str_season_maze_s3_help_disc_402 = "啟迪者根據夢境能量的波動情況，將夢境劃分成不同的「夢域」。導航員只能在「夢域」之間行走，在各個「夢域」觸發不同的事件。",
  str_season_maze_s3_help_disc_403 = "導航員可借助「卜夢卡」的力量在各個夢域之間移動。「卜夢卡」的「行動步數」決定導航員可以移動的「夢域」數量；部分「卜夢卡」還會附帶額外資源或特殊效果。每回合開始時，啟迪者會從牌庫中抽取一些「卜夢卡」，由導航員打出一張或直接拖曳至畫面，即可執行該「卜夢卡」的效果。",
  str_season_maze_s3_help_disc_404 = "導航員可在夢境中獲得各種資源。「夢境金幣」可購買各類道具，「夢境經驗」可提升「夢境等級」，「夢境利息」可提升每回合獲得的「夢境金幣」數量，「回合」則確保導航員在夢境中探索的安全。",
  str_season_maze_s3_help_disc_405 = "在「攜行包」可確認本次探索中加入編隊的光靈、已獲得的「夢境裝具」，和已加入牌庫的「卜夢卡」。",
  str_season_maze_s3_help_disc_406 = "夢境原主人遺落的記憶和情緒，被夢境能量層層包裹之後，便形成「幻珠」。此處可確認本次探索中獲得的「幻珠」，並進行裝配與合成等動作。",
  str_season_maze_s3_help_disc_407 = "「噬夢暗影」會在指定回合後對導航員發動突襲。必須戰勝「噬夢暗影」才能繼續探索夢境。「終極噬夢者」是最後一隻「噬夢暗影」，戰勝「終極噬夢者」就能結束探索，並根據夢境層級和探索進度獲得「夢境積分」。",
  str_season_maze_s3_help_disc_408 = "此處列出本次戰鬥的戰場特性和敵方資訊，方便導航員調整戰鬥策略。完成挑戰可獲得獎勵，若失敗可消耗「回合」重新挑戰。",
  str_season_maze_s3_help_disc_409 = "探索過程中獲得的「夢境經驗」可用來提升「夢境等級」。提高「夢境等級」可提升光靈等級、裝備等級，並獲得新的「卜夢卡」和「助夢道具」，有助於探索夢境。",
  str_season_maze_s3_help_disc_501 = "進入「危險夢域」與敵方交戰，獲勝即有機會選擇1件「夢境裝具」。",
  str_season_maze_s3_help_disc_502 = "進入「未知夢域」會觸發隨機事件。部分事件需要抽取3張「卜夢卡」並判定點數之和的大小，判定成功即可獲得獎勵。",
  str_season_maze_s3_help_disc_503 = "進入「資源夢域」可獲得對應類型的資源，包括「夢境金幣」、「夢境經驗」、「幻珠」。進入該「夢域」前的移動步數越長，獎勵越豐富。",
  str_season_maze_s3_help_disc_504 = "進入「待墾夢域」可派遣光靈執行任務，派遣越多回合收益越高。光靈在派遣期間無法參與戰鬥，派遣結束後自動歸隊。",
  str_season_maze_s3_help_disc_505 = "進入「祕寶夢域」可從多種獎勵選擇獲得一種。",
  str_season_maze_s3_help_disc_506 = "進入「夢域隧道」可使「噬夢暗影」的突襲時間延遲1回合。",
  str_season_maze_s3_help_disc_507 = "進入「空白夢域」不會觸發任何效果。",
  str_season_maze_s3_help_disc_508 = "進入「卜夢夢域」可花費「夢境金幣」重設或刪去現有的「卜夢卡」。",
  str_season_maze_s3_help_disc_509 = "在「流通夢域」可購買幻珠，第一顆幻珠免費。",
  str_season_maze_s3_help_disc_510 = "導航員可在「安全夢域」中休息，並透過召喚光靈、代購物品、購買藥品或復活光靈等手段來增強實力。此外，將「夢境金幣」注入「熔夢爐」可為未來的挑戰解鎖更多強力道具。",
  str_season_maze_s3_help_disc_511 = "「傳送夢域」會將你直接傳送到對應的「傳送夢域」，且不會途徑其他夢域。請注意，此為單向傳送。",
  str_season_maze_s3_help_disc_512 = "在「採購夢域」中可購買「夢境裝具」。",
  str_season_maze_s3_help_disc_513 = "進入「召喚夢域」可選擇一個屬性，召喚該屬性的光靈。請注意，一旦選定屬性，本次召喚中將無法更改為其他屬性。",
  str_season_maze_s3_help_disc_601 = "導航員可召喚光靈加入編隊。編隊中的光靈將繼承夢境外的光靈突破等級，但不會繼承其餘養成屬性和等級。提升「夢境等級」將提高夢境中的光靈等級和裝備等級。",
  str_season_maze_s3_help_disc_602 = "「夢境裝具」是長久以來勇於在夢境中探險的入夢者所遺落的珍貴知識與寶貴遺物。「夢境裝具」能觸發各種效果，有助於導航員探索夢境。",
  str_season_maze_s3_help_disc_603 = "導航員可借助「卜夢卡」的力量在各個夢域之間移動。「卜夢卡」的「行動步數」決定導航員可以移動的「夢域」數量；部分「卜夢卡」還會附帶額外資源或特殊效果，諸如「夢境金幣」、「夢境利息」、「夢境經驗」、「回合」等等。",
  str_season_maze_s3_help_disc_604 = "夢境原主人遺落的記憶和情緒，被夢境能量層層包裹之後，便形成「幻珠」。「幻珠」可提升導航員在夢境中的戰鬥力，小心不要被「噬夢暗影」撿走了！",
  str_season_maze_s3_help_disc_605 = "「助夢道具」是夢境能量依附夢境中，對現實物品的「記憶」偶然風化而成的物品。「助夢道具」具有各種有利效果，善加利用「助夢道具」幫助探索吧。",
  str_season_maze_s3_help_disc_701 = "幻珠有3種類型：技能珠、強化珠、蓄能珠。「技能珠」是戰鬥中實際施放的技能；「強化珠」會強化裝配的其他幻珠；「蓄能珠」會增加戰鬥中獲得的能量。",
  str_season_maze_s3_help_disc_702 = "戰鬥中光靈每連線移動1格，會獲得1點幻珠能量。連線結束後，若玩家累積的能量大於幻珠的能量需求，便會從左到右依序施放幻珠的技能。",
  str_season_maze_s3_help_disc_703 = "幻珠分為4個等級，最高為3星。幻珠的等級越高，效果越強。",
  str_season_maze_s3_help_disc_704 = "等級相同的2顆幻珠可以合成1顆高1等的幻珠。合成2顆同類型幻珠，必定獲得1顆該類型幻珠；合成2顆同名幻珠，必定獲得1顆同名幻珠；如果2顆幻珠類型不同，則獲得1顆隨機幻珠。",
  str_season_maze_s3_help_disc_705 = "夢境殘響挑戰結束後，裝配等級最高的5顆幻珠可以保留到下一次挑戰。裝配幻珠數量不足時，會保留背包中等級最高的幻珠。保留的幻珠等級會重設為1級。",
  str_season_maze_s3_guide_warn_90021101 = "在「待墾夢域」可派遣光靈執行任務，派遣越多回合收益越高。光靈在派遣期間無法參與戰鬥，派遣結束後自動歸隊。",
  str_season_maze_s3_guide_warn_90021102 = "點此可以派遣一名任意光靈，光靈在派遣期間無法加入編隊，派遣結束後自動歸隊。",
  str_season_maze_s3_mail_gm_season = "夢境殘響",
  str_season_maze_s3_mail_title_season = "未領取獎勵",
  str_season_maze_s3_mail_detail_season = "「夢境殘響」活動已結束，這是您在本次活動未領取的獎勵，請查收。"
}
return config
